import { Agent } from "@mastra/core/agent";
import { createTool } from "@mastra/core/tools";
import type { LanguageModelV4, LanguageModelV4CallOptions, LanguageModelV4Content, LanguageModelV4StreamPart } from "@ai-sdk/provider";
import { z } from "zod";

const usage = { inputTokens: { total: 10, noCache: 10, cacheRead: 0, cacheWrite: 0 }, outputTokens: { total: 5, text: 5, reasoning: 0 } };

function decide(opts: LanguageModelV4CallOptions): LanguageModelV4Content[] {
  const last = opts.prompt[opts.prompt.length - 1];
  if (last?.role === "tool") return [{ type: "text", text: "Added." }];
  return [{ type: "tool-call", toolCallId: "c1", toolName: "capture", input: JSON.stringify({ text: "oat milk" }) }];
}

const model: LanguageModelV4 = {
  specificationVersion: "v4",
  provider: "practice",
  modelId: "practice-1",
  supportedUrls: {},
  async doGenerate(opts) {
    const content = decide(opts);
    return { content, finishReason: { unified: content.some((c) => c.type === "tool-call") ? "tool-calls" : "stop", raw: undefined }, usage, warnings: [] };
  },
  async doStream(opts) {
    const content = decide(opts);
    const parts: LanguageModelV4StreamPart[] = [{ type: "stream-start", warnings: [] }];
    for (const c of content) {
      if (c.type === "text") { parts.push({ type: "text-start", id: "t" }, { type: "text-delta", id: "t", delta: c.text }, { type: "text-end", id: "t" }); }
      else parts.push(c);
    }
    parts.push({ type: "finish", finishReason: { unified: content.some((c) => c.type === "tool-call") ? "tool-calls" : "stop", raw: undefined }, usage });
    return { stream: new ReadableStream({ start(ctl) { for (const p of parts) ctl.enqueue(p); ctl.close(); } }) };
  },
};

const capture = createTool({
  id: "capture",
  description: "capture",
  inputSchema: z.object({ text: z.string() }),
  execute: async (input) => { console.log("TOOL", input); return { ok: true }; },
});

const agent = new Agent({ id: "house", name: "house", instructions: "x", model, tools: { capture } });
const r = await agent.generate("we're out of oat milk");
console.log("TEXT", r.text, r.usage, r.toolCalls?.length);
EOF
npx tsx server/agent/proto.ts 2>&1 | tail -20

