/**
 * CODE-13/14/15: every limit the system imposes, in one place, each with the reason
 * that justifies it. A limit at a call site must reference a constant from this file
 * and carry an adjacent `// limit: <REASON>` comment; the linter rejects anything else.
 *
 * Only these reasons count:
 */
export const LimitReason = {
  /** OWASP Top 10 for LLM Applications 2025 — LLM10: Unbounded Consumption. */
  OWASP_LLM10: "https://genai.owasp.org/llmrisk/llm102025-unbounded-consumption/",
  /** OWASP Top 10 for LLM Applications 2025 — LLM01: Prompt Injection. */
  OWASP_LLM01: "https://genai.owasp.org/llmrisk/llm01-prompt-injection/",
  /** OWASP Top 10 for LLM Applications 2025 — LLM06: Excessive Agency. */
  OWASP_LLM06: "https://genai.owasp.org/llmrisk/llm062025-excessive-agency/",
  /** OWASP API Security Top 10 2023 — API4: Unrestricted Resource Consumption. */
  OWASP_API4: "https://owasp.org/API-Security/editions/2023/en/0xa4-unrestricted-resource-consumption/",
  /** A provider's documented hard limit. */
  PROVIDER_HARD_LIMIT: "provider documentation",
  /** A line in VERIFICATIONS.md; the constant names the line ID. */
  VERIFICATION: "VERIFICATIONS.md",
} as const;
export type LimitReason = keyof typeof LimitReason;

/** limit: OWASP_LLM10 / OWASP_API4 — an inbound message is a thought, not a document. */
export const MAX_INBOUND_TEXT_CHARS = 4000;

/** limit: OWASP_LLM06 / OWASP_LLM10 — the agent may take at most this many tool steps per job. */
export const AGENT_MAX_STEPS = 6;

/** limit: VERIFICATION MOM-9 — never more than three sentences unless asked for more. */
export const REPLY_MAX_SENTENCES = 3;

/** limit: VERIFICATION CAP-5 — "not now" three times parks an item. */
export const NOT_NOW_PARK_THRESHOLD = 3;

/** limit: VERIFICATION PRO-6 — at most one backlog item offered per day. */
export const BACKLOG_OFFERS_PER_DAY = 1;

/** limit: VERIFICATION PRO-7 — default messages per person per day. */
export const DEFAULT_DAILY_MESSAGE_BUDGET = 3;

/** limit: VERIFICATION PRO-7 — default quiet hours, local time. */
export const DEFAULT_QUIET_START_HOUR = 21;
export const DEFAULT_QUIET_END_HOUR = 7;

