      return c.redirect(`/login?next=${encodeURIComponent(p)}`);
    }
    c.set("person", person);
    return next();
  });

  app.all("/api/trpc/*", (c) =>
    fetchRequestHandler({
      endpoint: "/api/trpc",
      req: c.req.raw,
