        const topic = queue.shift();
        if (topic !== undefined) {
          await stream.writeSSE({ event: "change", data: JSON.stringify({ topic }) });
          continue;
        }
        await new Promise<void>((resolve) => {
          wake = resolve;
          setTimeout(resolve, 25_000);
