import { DBOS } from "@dbos-inc/dbos-sdk";
import { AttachmentKind, Channel, type TimerKind, zTimerKind } from "@household/contracts";
import { accept } from "../../coordinator/accept.ts";
import type { Runtime } from "../../runtime.ts";
import type { Adapter } from "../registry.ts";
import { cronOf, expectedFires, SCHEDULES } from "./schedule.ts";

let runtime: Runtime | null = null;

/** A timer is a message like any other (CH-5): household, no person, the timer channel, a dedupe key. */
export async function fireTimer(rt: Runtime, timer: TimerKind, scheduledFor: Date) {
  return accept(rt, {
    household: rt.env.HOUSEHOLD_ID,
    person: null,
    channel: Channel.timer,
    text: timer,
    attachments: [{ kind: AttachmentKind.timer, timer, scheduledFor: scheduledFor.toISOString() }],
    dedupeKey: `timer:${timer}:${scheduledFor.toISOString()}`,
    receivedAt: rt.ports.clock.now().toISOString(),
  });
}

/** PLT-10: a timer firing is a DBOS scheduled workflow, not a cron process. It only hands a message to the coordinator. */
const timerFired = DBOS.registerWorkflow(
  async (scheduledDate: Date, context: unknown) => {
    const rt = runtime;
    if (rt === null) throw new Error("timers adapter not started");
