/** A timer is a message like any other (CH-5): household, no person, the timer channel, a dedupe key. */
export async function fireTimer(rt: Runtime, timer: TimerKind, scheduledFor: Date) {
  return accept(rt, {
    household: rt.env.HOUSEHOLD_ID,
    person: null,
    channel: Channel.timer,
    text: timer,
    attachments: [{ kind: AttachmentKind.timer, timer, scheduledFor: scheduledFor.toISOString() }],
