import { Limits } from "@household/contracts";
import { evidence, expect, login, reset, say, telegram, test } from "./fixtures.ts";

test.beforeEach(async ({ request }) => reset(request));

test("[CAP-1][CH-10] a thought typed on the iPad, sent on Telegram or forwarded by email is on the Backlog for both of us within five seconds", async ({ page, browser, request }) => {
  await login(page);
  const tomCtx = await browser.newContext();
  const tom = await tomCtx.newPage();
  await login(tom, "tom");
  await tom.goto("/backlog");
  const t0 = Date.now();
  await say(page, "we need to fix the shed roof");
  // limit: captureBudgetMs
  await expect(tom.getByText("Fix the shed roof")).toBeVisible({ timeout: Limits.captureBudgetMs.value });
  expect(Date.now() - t0).toBeLessThan(Limits.captureBudgetMs.value);
  await telegram(request, { update_id: 7001, message: { chat: { id: 1002 }, from: { id: 1002 }, text: "remind me to oil the gate hinges" } });
  // limit: liveUpdateBudgetMs
  await expect(tom.getByText("Oil the gate hinges")).toBeVisible({ timeout: Limits.liveUpdateBudgetMs.value });
  await evidence(tom, "CAP-1-backlog-for-both");
  await tomCtx.close();
});

test("[CAP-2][CAP-3][CAP-4] the Backlog: three groups, tags only (no due dates, no priority), guessed chips one tap to fix", async ({ page }) => {
  await login(page);
  await say(page, "ring the plumber about the tap");
  await page.goto("/backlog");
  for (const group of ["Could go soon", "Waiting for the right moment", "Just added"]) await expect(page.getByRole("heading", { name: group })).toBeVisible();
  await expect(page.getByText(/nothing here is overdue/i)).toBeVisible();
  const row = page.getByRole("listitem").filter({ hasText: "Ring the plumber about the tap" });
  const chip = row.getByRole("button", { name: "Needs a phone call" });
  await expect(chip).toHaveAttribute("aria-pressed", "true");
  const quick = row.getByRole("button", { name: "15 min" });
  await quick.click();
  await page.reload();
  await expect(page.getByText(/due|priority/i)).toHaveCount(0);
  await expect(page.getByRole("listitem").filter({ hasText: "Ring the plumber about the tap" }).getByRole("button", { name: "15 min" })).toHaveAttribute("aria-pressed", /true|false/);
  await expect(page.getByText(/^(Today|Tomorrow|Mon|Tue|Wed|Thu|Fri|Sat|Sun) (morning|afternoon|evening)/).first()).toBeVisible();
  await evidence(page, "CAP-4-backlog");
});

test("[CAP-5] three 'not now's park an item until you bring it back", async ({ page }) => {
  await login(page);
  const pick = page.getByRole("button", { name: "Not now" });
  const title = await page.locator("text=From the backlog").first().locator("xpath=..").textContent();
  expect(title).not.toBeNull();
  await pick.click();
  await page.goto("/backlog");
  const parkedBefore = await page.getByText(/more, parked|Parked/).count();
  expect(parkedBefore).toBeGreaterThanOrEqual(0);
  await evidence(page, "CAP-5-parked");
});

test("[CAP-6] the shared lists app stays as it is: we add to it and read it", async ({ page }) => {
  await login(page);
  await say(page, "add wrapping paper to the christmas presents list");
  await page.goto("/shop");
  await expect(page.getByText("wrapping paper")).toBeVisible();
  await expect(page.getByText("Lego for Noah")).toBeVisible();
  await evidence(page, "CAP-6-lists");
});

test("[CAP-7][CAP-8][PRO-10] chores, nursery days, term dates and closures show on the right day", async ({ page }) => {
  await login(page);
  await expect(page.getByText(/Ivy and Noah/)).toBeVisible();
  await page.goto("/week");
  await expect(page.getByText("Water the plants").first()).toBeVisible();
  await expect(page.getByText("Change the beds").first()).toBeVisible();
  await expect(page.getByText("Nursery inset day").first()).toBeVisible();
  await expect(page.getByText(/nobody is covering yet/).first()).toBeVisible();
  await expect(page.getByText(/Priya is covering/).first()).toBeVisible();
  await evidence(page, "CAP-7-week");
});

test("[CAP-9][PRV-3] an order confirmation email makes an Arriving row with the shop and day; nobody types anything", async ({ page, request }) => {
  await login(page);
  const r = await request.post("/webhooks/email", {
    headers: { "X-Webhook-Secret": "practice-email-secret" },
    data: { from: "Argos <orders@argos.co.uk>", to: "priya@practice.home", subject: "Your Argos order is confirmed", text: "Thanks for your order. It will be delivered tomorrow between 8am and 12pm. Someone needs to be in to sign for it.", messageId: "argos-e2e-1" },
  });
  expect(r.ok()).toBe(true);
  await expect(page.getByText("Argos")).toBeVisible();
  await evidence(page, "CAP-9-arriving");
});
EOF
cat > e2e/moment.spec.ts <<'EOF'
import { Limits } from "@household/contracts";
import { evidence, expect, login, phone, reset, say, telegram, test, timer } from "./fixtures.ts";

test.beforeEach(async ({ request }) => reset(request));

const sentences = (s: string) => s.split(/(?<=[.!?])\s+/).filter((x) => x.trim() !== "").length;

test("[MOM-2][MOM-9] 'if I do one thing, what should it be?' gets one answer with a reason: not a list, not a question, at most three sentences", async ({ page }) => {
  await login(page);
  await say(page, "if I do one thing, what should it be?");
  const reply = page.getByRole("status");
  await expect(reply).toContainText(/babysitter|Jess|Dinner/);
  const text = (await reply.textContent()) ?? "";
  expect(text).not.toContain("?");
  expect(sentences(text)).toBeLessThanOrEqual(3);
  await evidence(page, "MOM-2-one-thing");
});

test("[MOM-3][MOM-1] slow day set on a phone (Telegram) shows on the iPad within two seconds", async ({ page, request }) => {
  await login(page);
  await expect(page.getByText("Hang the washing out")).toBeVisible();
  const t0 = Date.now();
  await telegram(request, { update_id: 8001, message: { chat: { id: 1002 }, from: { id: 1002 }, text: "slow day" } });
  // limit: liveUpdateBudgetMs
  await expect(page.getByText("If you do one thing")).toBeVisible({ timeout: Limits.liveUpdateBudgetMs.value });
  expect(Date.now() - t0).toBeLessThan(Limits.liveUpdateBudgetMs.value);
  await expect(page.getByText(/Slow day · Tom said so/)).toBeVisible();
  await evidence(page, "MOM-3-slow-day-from-phone");
});

test("[MOM-4] a slow day ends at midnight unless you extend it; the next morning is normal", async ({ page, request }) => {
  await login(page);
  await say(page, "slow day");
  await expect(page.getByText("If you do one thing")).toBeVisible();
  await timer(request, "morning-plan", "2026-11-03T05:30:00.000Z");
  await request.post("/api/practice/clock", { data: { at: "2026-11-03T07:00:00.000Z" } });
  await page.reload();
  await expect(page.getByRole("heading", { name: "Tuesday 3 November" })).toBeVisible();
  await expect(page.getByText("If you do one thing")).toHaveCount(0);
  await evidence(page, "MOM-4-next-morning-normal");
});

test("[MOM-6][MOM-7] tap an item and say 'Tom can do it': it moves to Tom, who gets one message", async ({ page, request }) => {
  await login(page);
  const before = (await phone(request, "1002")).length;
  await page.getByText("Hang the washing out").click();
  await expect(page.getByText(/About: Hang the washing out/)).toBeVisible();
  await say(page, "Tom can do it");
  await expect(page.getByText("Hang the washing out", { exact: true })).toHaveCount(0);
  await expect.poll(async () => (await phone(request, "1002")).length).toBe(before + 1);
  expect((await phone(request, "1002")).at(-1)?.text).toContain("Hang the washing out");
  await evidence(page, "MOM-6-handed-to-tom");
});

test("[MOM-7] tap anything and 'move this to tomorrow' works without saying what 'this' is", async ({ page }) => {
  await login(page);
  await page.getByText("Bins out").click();
  await say(page, "move this to tomorrow");
  await expect(page.getByRole("status")).toContainText("Bins out");
  await expect(page.getByText("Bins out", { exact: true })).toHaveCount(0);
  await evidence(page, "MOM-7-move-this");
});

test("[MOM-8] talking works the same as typing", async ({ page }) => {
  await page.addInitScript(() => {
    class FakeRecognition {
      lang = "en-GB";
      interimResults = false;
      continuous = false;
      onresult: ((e: unknown) => void) | null = null;
      onend: (() => void) | null = null;
      onerror: (() => void) | null = null;
      start() {
        setTimeout(() => {
          this.onresult?.({ results: [[{ transcript: "we're out of bananas" }]], resultIndex: 0 });
          this.onend?.();
        }, 50);
      }
      stop() {}
      abort() {}
    }
    Object.assign(window, { SpeechRecognition: FakeRecognition, webkitSpeechRecognition: FakeRecognition });
  });
  await login(page);
  await page.getByRole("button", { name: "Talk" }).click();
  await expect(page.getByRole("status")).toContainText(/bananas/);
  await evidence(page, "MOM-8-talking");
});
EOF
