      expect(text.match(/export function \w+Router\(/g)).toHaveLength(1);
      expect(text).toContain("@household/contracts");
    }
  });

  test("[CODE-6] every foreign key is declared twice: on the column and as a relations() entry", () => {
    for (const [domain, mod] of Object.entries(schemas)) {
      const entries = Object.entries(mod as Record<string, unknown>);
      const tables = entries.filter(([, v]) => typeof v === "object" && v !== null && Symbol.for("drizzle:IsDrizzleTable") in v) as [string, PgTable][];
      const relations = entries.filter(([k]) => k.endsWith("Relations")).map(([, v]) => v as { table: PgTable; config: (h: unknown) => Record<string, unknown> });
      for (const [name, table] of tables) {
        for (const fk of getTableConfig(table).foreignKeys) {
