const q = async (query, variables = {}) => (await (await fetch("https://api.linear.app/graphql", { method: "POST", headers: { "content-type": "application/json", authorization: process.env.LINEAR_API_KEY }, body: JSON.stringify({ query, variables }) })).json());
const r = await q('query { issues(first: 200, filter: { project: { name: { eq: "Household Coordinator — Verifications" } } }) { nodes { title comments(first: 10) { nodes { body } } } } }');
const n = r.data.issues.nodes;
const counts = n.map((i) => i.comments.nodes.length);
console.log("issues", n.length, "max comments", Math.max(...counts), "issues with >1:", n.filter((i) => i.comments.nodes.length > 1).map((i) => i.title.split(" ")[0]).join(","));
EOF
